<script setup>
import {useForm,Link,usePage} from '@inertiajs/vue3';import {ref} from 'vue';import PlatformAdminLayout from '@/Layouts/PlatformAdminLayout.vue';import AppNotice from '@/Components/Product/AppNotice.vue';import '../../../css/marketplace.css';defineProps({reports:Object});const form=useForm({status:'resolved',note:''});const editing=ref('');
</script>
<template><PlatformAdminLayout title="Marketplace concerns"><main class="market mp-container"><h1 class="mp-title">Marketplace concerns</h1><AppNotice v-if="usePage().props.marketplaceStatus" :title="usePage().props.marketplaceStatus" /><AppNotice v-if="!reports.data.length" title="No concerns have been reported" /><article v-for="report in reports.data" :key="report.reference" class="mp-card"><h2>{{report.salon}}</h2><p class="mp-muted">{{report.reference}} · {{report.reason}} · {{report.status}}</p><p style="white-space:pre-wrap;overflow-wrap:anywhere">{{report.details}}</p><div class="mp-actions"><button class="mp-button secondary" @click="editing=report.reference;form.reset()">Review concern</button></div><form v-if="editing===report.reference" @submit.prevent="form.patch(report.url,{onSuccess:()=>editing=''})"><label class="mp-field"><span>Status</span><select v-model="form.status"><option value="resolved">Resolved</option><option value="open">Open</option></select></label><label class="mp-field"><span>Operator recovery note</span><textarea v-model="form.note" required maxlength="1000" /></label><p class="mp-error" v-if="form.errors.note">{{form.errors.note}}</p><button class="mp-button" :disabled="form.processing">Save review</button></form></article><nav class="mp-pagination"><Link v-if="reports.prev_page_url" :href="reports.prev_page_url">Previous</Link><Link v-if="reports.next_page_url" :href="reports.next_page_url">Next</Link></nav></main></PlatformAdminLayout></template>
